INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d0dc67de-6baf-582d-ad19-6d23a90609b5'::uuid, 'c5d3b6bf-f7a3-5774-abd8-b670f8b93e66'::uuid, 'Construction d’une maison d’accouchement', 'Al MIDYAF a été chargée des travaux de construction d’une Maison d’accouchement dans la commune de Souk El-Tlet Gharb, en assurant l’exécution des tâches relatives à l’édification de ce projet stratégique qui vise à améliorer les infrastructures sanitaires de la région, en offrant des services de santé de qualité aux mères et aux nouveau-nés.', '["https://lechantier.ma/uploads/media/526ba5a4c2a7.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/526ba5a4c2a7.webp', 'Khémisset', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('003ffa20-9889-5bdd-868d-d28a2152535c'::uuid, 'ac5a28a1-bb41-5752-90ae-e1b5bfc5a104'::uuid, 'Villa - Almaz Casablanca', 'Villa en cours de construction (R+1) , avec structure solide en béton armé . Les murs sont doublés pour plus de solidité et d’isolation. Le coffrage est réalisé avec des panneaux spéciaux pour un béton brut et propre . Travaux réalisés avec précision et selon les normes.', '["https://lechantier.ma/uploads/media/b6f11cf661fd.webp", "https://lechantier.ma/uploads/media/8b15e0898fb9.webp", "https://lechantier.ma/uploads/media/cb1a46a4a2ec.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/b6f11cf661fd.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6be03f2a-e4b7-577a-aa9c-d30554704acf'::uuid, 'ac5a28a1-bb41-5752-90ae-e1b5bfc5a104'::uuid, 'Villa - Quartier Almaz Casablanca', 'Travaux de gros œuvre d’une villa haut standing : structure en béton armé avec coffrage en panneaux bakélisés pour un béton brut de qualité. Maçonnerie en double cloison pour une meilleure isolation et solidité. Escaliers type crémaillère intégrés dans la structure. Exécution précise conforme aux normes techniques du bâtiment.', '["https://lechantier.ma/uploads/media/c3eabaafefed.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/c3eabaafefed.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
