INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9a23a56e-e21f-5987-b695-5fecae3a1576'::uuid, 'f9d1dcdb-7dd0-5a3a-b379-eb2f676ea303'::uuid, 'Construction d’un immeuble résidentiel', 'Ce projet consiste en la construction complète d’un immeuble résidentiel comprenant 3 étages et un sous-sol. Nos équipes spécialisées assurent la réalisation de tous les travaux de gros œuvre, second œuvre, installations électriques et pose d’aluminium pour offrir un projet clé en main, dans le respect des normes et des délais impartis.', '["https://lechantier.ma/uploads/media/7c79d9d8f7d3.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/7c79d9d8f7d3.webp', 'qui répond aux attentes du client et g', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('75bf85de-1e08-58d7-ae7b-b04e1e3c5d32'::uuid, 'f9d1dcdb-7dd0-5a3a-b379-eb2f676ea303'::uuid, 'Construction d’une villa moderne avec pi', 'Ce projet comprend la construction complète d’une villa moderne et spacieuse avec piscine. Nous assurons toutes les étapes, des fondations à la finition, en incluant la maçonnerie, l’installation électrique, la pose d’aluminium et la réalisation de la piscine. Notre objectif est de livrer une villa clé en main qui répond aux attentes du client et g', '[]'::jsonb, NULL, 'qui répond aux attentes du client et g', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('bec43ad5-501f-5349-8e5f-8c9c33e1343b'::uuid, '8171fa89-b72a-53b7-bf16-267acf341113'::uuid, 'Réalisation — YT UNIVERSEL', '📍étage 1 Appt N°3, Résidence Rif II IMM N B 01- Rabat, Temara', '["https://lechantier.ma/uploads/media/bc3e7035de18.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/bc3e7035de18.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
