INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('91917c79-e932-5423-a7e3-2b8989c11478'::uuid, 'b971e8b6-57ee-5bfd-bc9c-375b605c4363'::uuid, 'Villa', 'L’un des premiers projets sur lesquels nous avons travaillé est une villa de environ 483 mètres carrés (soit 5 200 pieds carrés). Ce projet nous a permis de mettre en œuvre notre expertise dans la conception et la réalisation de bâtiments résidentiels haut de gamme. L’accent a été mis sur l’optimisation de l’espace, la qualité des matériaux utilisé', '["https://lechantier.ma/uploads/media/2d2069d69042.webp", "https://lechantier.ma/uploads/media/3b094fd764bf.webp", "https://lechantier.ma/uploads/media/cf5b46ebe4ed.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/2d2069d69042.webp', 'Safi', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('faa6df99-b7a7-5a55-a1c9-c0a36098959b'::uuid, 'b971e8b6-57ee-5bfd-bc9c-375b605c4363'::uuid, 'Immeuble R+5', 'Ce projet concerne la réalisation d’un immeuble R+5 (rez-de-chaussée + 5 étages), destiné à un usage résidentiel et/ou commercial. L’objectif principal était d’optimiser la densité du terrain tout en garantissant une circulation fluide et un confort optimal pour les occupants. L’immeuble comprend des espaces bien répartis sur chaque étage, avec un', '["https://lechantier.ma/uploads/media/ac393369840f.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ac393369840f.webp', 'Safi', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
