INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e0aeaa04-7c8d-53e1-83b0-40994efd0ebe'::uuid, '49ea93b1-4772-567e-aef7-21f1471be4c0'::uuid, 'Finition d’une villa – Clé en main', 'Réalisation complète de la finition d’une villa clé en main à Marrakech, avec conception et pose de menuiseries aluminium sur mesure : baies vitrées, portes coulissantes, fenêtres et garde-corps. Finitions haut standing offrant isolation thermique et acoustique optimale. ✅', '["https://lechantier.ma/uploads/media/e6ec59822a26.webp", "https://lechantier.ma/uploads/media/2374bc579fcd.webp", "https://lechantier.ma/uploads/media/0da293206182.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/e6ec59822a26.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('f509bee7-e9b9-5550-ae81-68a7a7934ddc'::uuid, '49ea93b1-4772-567e-aef7-21f1471be4c0'::uuid, 'Construction d''une villa - Clé en main', 'Projet de construction d’une villa haut standing à Marrakech, livré clé en main. Nous assurons toutes les étapes : conception, autorisations, gros œuvre, finitions et remise des clés. Un accompagnement complet pour un résultat conforme aux attentes de notre client.', '["https://lechantier.ma/uploads/media/87f8e72195c7.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/87f8e72195c7.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
