INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('4d90dbc9-6a84-5100-99ac-5b2b54049302'::uuid, '12b7b35f-0bb8-5cc7-b259-02ec5bedaaee'::uuid, 'Construction d’un immeuble R+4', 'Il s’agit d’un immeuble résidentiel et commercial composé d’un sous-sol destiné au stationnement et aux locaux techniques, d’un rez-de-chaussée avec mezzanine pouvant accueillir des commerces ou des bureaux, et de quatre étages supérieurs à usage d’habitation. La conception allie fonctionnalité et confort, offrant des espaces modernes', '["https://lechantier.ma/uploads/media/ef11634047ce.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ef11634047ce.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
