INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('aa744901-9d29-53c7-ab31-b7ff3a1b635f'::uuid, 'abc74fab-393e-5337-80b5-6653df1cb545'::uuid, 'Résidence Les Orangers B - Souissi', 'Situé dans le quartier prisé de Souissi à Rabat, le projet Les Orangers Souissi est une réalisation haut standing regroupant 36 appartements de prestige et 12 commerces en rez-de-chaussée. Conçu dans un esprit contemporain et élégant, le projet allie architecture moderne, matériaux nobles et qualité d’exécution tous corps d’état.', '["https://lechantier.ma/uploads/media/b47edfc0676c.webp", "https://lechantier.ma/uploads/media/dd82d06d3662.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/b47edfc0676c.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('7e3faeec-e188-5e5a-b4d7-62850b5cefe1'::uuid, 'abc74fab-393e-5337-80b5-6653df1cb545'::uuid, 'Immeuble Arinass - Témara', 'Le projet ARINASS est un immeuble résidentiel réalisé en partenariat avec un promoteur local à Témara, comprenant 12 appartements et 4 locaux commerciaux. Entièrement exécuté tous corps d’état, le projet a été livré en 12 mois, dans le respect des normes de qualité, de sécurité et des délais fixés.', '["https://lechantier.ma/uploads/media/5d4d6424cd12.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5d4d6424cd12.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
