INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('71da6cc7-4a62-588c-99df-af1ee5d105d7'::uuid, '7f3c48c1-bc8e-586e-b9c8-e1fc1718987d'::uuid, 'Villa Sécurisée avec autonomie en Eau​💧', '​Ce projet, réalisé pour un client (MRE), illustre notre engagement à fournir un Gros Œuvre qui dépasse les attentes locales. Il ne s''agit pas seulement de construire, mais d''ériger les fondations d''une vie autonome et sécurisée au Maroc. Notre expertise a permis d''intégrer des fonctionnalités complexes dès la structure', '["https://lechantier.ma/uploads/media/712e504c911f.webp", "https://lechantier.ma/uploads/media/d6b018e551f1.webp", "https://lechantier.ma/uploads/media/512bf15e9da3.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/712e504c911f.webp', 'El Jadida', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('02d7d9d1-b369-550d-bc72-ad52cf1ba922'::uuid, '7f3c48c1-bc8e-586e-b9c8-e1fc1718987d'::uuid, 'Villa en Zone Côtière', '​Dans le cadre de ce projet de villa en zone sélective, la plus grande réussite de Family Capital Company réside dans l''exécution rigoureuse d''un plan d''architecte entièrement personnalisé et dicté par les souhaits spécifiques de la cliente.', '["https://lechantier.ma/uploads/media/5939e6bb7251.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5939e6bb7251.webp', 'El Jadida', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
