INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('b3603424-4ab3-5662-a1d0-07baba1dbd0e'::uuid, 'd2449473-1eb0-5344-a9dd-2a7736b79252'::uuid, 'Immeubles Al Alia El Jadida', 'Le projet Al Alia, réalisé en 2022 à El Jadida, porte sur la construction d’appartements économiques. Il comprend plusieurs immeubles résidentiels conçus pour offrir des logements fonctionnels et accessibles. Les travaux ont englobé le gros œuvre, le second œuvre ainsi que les aménagements extérieurs, en conformité avec les normes de qualité.', '["https://lechantier.ma/uploads/media/5bfce5316bf8.webp", "https://lechantier.ma/uploads/media/b4353b5050ff.webp", "https://lechantier.ma/uploads/media/fa09c13d79f3.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5bfce5316bf8.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('37f5ee90-67fc-5f90-8f1f-9a6a551b10f9'::uuid, 'd2449473-1eb0-5344-a9dd-2a7736b79252'::uuid, 'Diar lhamd 1 bouskoura', 'Le projet Dyar L’Hamd, réalisé en 2019 à Bouskoura, concerne la construction d’appartements économiques. Il comprend 32 immeubles, chacun composé de 16 appartements, soit un total de 512 logements. Les travaux ont inclus le gros œuvre, le second œuvre ainsi que les voiries et réseaux divers, dans le respect des normes de qualité et de sécurité.', '["https://lechantier.ma/uploads/media/1dc6f2afa629.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/1dc6f2afa629.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
